su - postgres -c "psql -p 5433 -v ON_ERROR_STOP=1 <<'SQL'
DO \$\$
BEGIN
  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'old_user') THEN
    CREATE ROLE old_user LOGIN;
  END IF;
  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'benchmark_user') THEN
    CREATE ROLE benchmark_user LOGIN PASSWORD 'benchmark_pass';
  ELSE
    ALTER ROLE benchmark_user WITH LOGIN PASSWORD 'benchmark_pass';
  END IF;
END
\$\$;
SQL"
echo "roles exit=$?"
# create database if not exists
su - postgres -c "psql -p 5433 -tAc \"SELECT 1 FROM pg_database WHERE datname='benchmark_db'\"" | grep -q 1 || su - postgres -c "createdb -p 5433 -O benchmark_user benchmark_db"
su - postgres -c "psql -p 5433 -tAc \"SELECT datname, pg_get_userbyid(datdba) FROM pg_database WHERE datname='benchmark_db'\""

cd /testbed/migrations
su - postgres -c "psql -p 5433 -d benchmark_db -v ON_ERROR_STOP=1 -f /testbed/migrations/02_create_schema.sql" && \
su - postgres -c "psql -p 5433 -d benchmark_db -v ON_ERROR_STOP=1 -f /testbed/migrations/01_seed_users.sql"
echo "migrations exit=$?"
# Grant access to benchmark_user on existing objects and future ones
su - postgres -c "psql -p 5433 -d benchmark_db -v ON_ERROR_STOP=1 <<'SQL'
GRANT old_user TO benchmark_user;
GRANT USAGE ON SCHEMA public TO benchmark_user;
GRANT ALL PRIVILEGES ON ALL TABLES IN SCHEMA public TO benchmark_user;
GRANT ALL PRIVILEGES ON ALL SEQUENCES IN SCHEMA public TO benchmark_user;
GRANT ALL PRIVILEGES ON DATABASE benchmark_db TO benchmark_user;
SQL"
echo "grants exit=$?"
